#
# The rule id is the identity: file name, control id and `tag checkov_id` all
# carry it, and tools/lint_catalog_drift.py asserts the three agree.

scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_88'] || []
applies_to   = %w[aws_instance aws_launch_template]

control 'CKV_AWS_88' do
  title 'EC2 instance should not have public IP'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the instances and launch templates that actually exist.
  DESC

  desc 'rationale', <<~RATIONALE
    A public IP puts the instance directly on the internet attack surface,
    rather than behind a load balancer or NAT where ingress can be reasoned
    about.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_instance: associate_public_ip_address is not
    True; aws_launch_template:
    network_interfaces/[0]/associate_public_ip_address is not True
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_instance:

      resource "aws_instance" "app" {
        ami                         = var.ami_id
        instance_type               = "t3.micro"
        subnet_id                   = var.private_subnet_id
        associate_public_ip_address = false
      }

    Note (aws_instance): A running instance cannot have its public IP detached.
    The Terraform change replaces the instance; there is no in-place CLI
    equivalent.

    Terraform — aws_launch_template:

      resource "aws_launch_template" "app" {
        name_prefix   = "app-"
        image_id      = var.ami_id
        instance_type = "t3.micro"

        network_interfaces {
          associate_public_ip_address = false
          subnet_id                   = var.private_subnet_id
        }
      }

    Out of band — aws_launch_template:

      Create a new launch template version; existing instances keep the address
      they were launched with until they are replaced.
  FIX

  tag checkov_id:       'CKV_AWS_88'
  tag checkov_category: 'NETWORKING'
  tag checkov_version:  '3.3.16'
  tag checkov_kind:     'negative'
  tag tf_resources:     %w[aws_instance aws_launch_template]
  tag tf_argument:      'associate_public_ip_address'
  tag tf_docs:          'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/instance#associate-public-ip-address'
  tag nist:             ['SC-7', 'SC-7 (5)']
  tag nist_r4:          ['SC-7', 'SC-7 (5)']
  tag cci:              ['CCI-001097', 'CCI-002080']
  tag ksi:              ['KSI-CNA-NDS']
  tag severity:         'medium'
  tag severity_source:  'assessed'
  tag nist_source:      'reviewed'
  tag implementation_status: 'implemented'

  assets = aws_compute_assets(regions: scan_regions)

  # aws_compute_assets records a denied or unreachable region rather than
  # swallowing it, and says why: "a control that treats it as 'nothing here'
  # passes vacuously". Nothing read it, so that is exactly what these controls
  # did. Asserted here, and carried into `applicable` below, because when every
  # region is denied there are zero rows AND an error — so only_if would
  # otherwise skip the control and this assertion along with it, rendering
  # impact 0.0 and Not Applicable over an estate nobody managed to look at.
  unreadable = assets.unreadable_regions
  unless unreadable.empty?
    describe 'aws_compute_assets enumeration' do
      it 'read every region it attempted' do
        expect(unreadable.map { |r| "#{r[:region]}: #{r[:error]}" }).to be_empty
      end
    end
  end

  # Only the asset types this check declares, only what the boundary has, and
  # only those that express the setting at all — a launch template has no
  # ebs_optimized, and nil must not read as a passing false.
  # A field the API did not return is nil, and nil is not a failing value:
  # the asset does not express this setting, so it is out of scope for this
  # check rather than in breach of it.
  in_scope = assets.assets_of(applies_to, exempt: exempt)
                   .reject { |a| a[:public_ip].nil? }

  applicable = !in_scope.empty? || !unreadable.empty?

  # Two statements, not a ternary: InSpec's AST impact collector calls `.value`
  # on the argument node, and a ternary is an IfNode with none — it aborts
  # `check` for the whole profile before a single control runs.
  impact 0.5
  impact 0.0 unless applicable

  only_if("no #{applies_to.join(', ')} in scope expressing this setting") { applicable }

  in_scope.each do |asset|
    describe "#{asset[:type]} #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:public_ip] }
      it { should be false }
    end
  end
end
